#!/usr/bin/env python3
import sys
import re
from bs4 import BeautifulSoup

def remove_javascript(html_content):
    soup = BeautifulSoup(html_content, 'html.parser')

    # Remove all script tags
    for script in soup.find_all('script'):
        script.decompose()

    # Remove all event handlers (attributes starting with 'on')
    for tag in soup.find_all(True):
        attrs = list(tag.attrs)
        for attr in attrs:
            if attr.lower().startswith('on'):
                del tag[attr]
            # Also check for javascript: in href, src, action, etc.
            if attr.lower() in ('href', 'src', 'action', 'formaction', 'background', 'cite', 'data', 'poster', 'profile', 'usemap'):
                value = tag[attr]
                if isinstance(value, str) and re.match(r'^\s*javascript:', value, re.I):
                    del tag[attr]
                elif isinstance(value, list):
                    # For attributes that can have multiple values (like class), we ignore
                    pass

    # Additional pass for any attribute value containing javascript: (catch-all)
    for tag in soup.find_all(True):
        for attr, value in list(tag.attrs.items()):
            if isinstance(value, str) and re.search(r'javascript:', value, re.I):
                del tag[attr]
            elif isinstance(value, list):
                # If any list item contains javascript:, we remove the whole attribute
                if any(re.search(r'javascript:', v, re.I) for v in value if isinstance(v, str)):
                    del tag[attr]

    # Return HTML as string preserving original formatting
    return str(soup)

def main():
    if len(sys.argv) != 2:
        print('Usage: python3 filter.py <html_file>')
        sys.exit(1)
    filename = sys.argv[1]
    try:
        with open(filename, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        print(f'Error reading file: {e}')
        sys.exit(1)

    new_content = remove_javascript(content)

    try:
        with open(filename, 'w', encoding='utf-8') as f:
            f.write(new_content)
    except Exception as e:
        print(f'Error writing file: {e}')
        sys.exit(1)

    print(f'Removed JavaScript from {filename}')

if __name__ == '__main__':
    main()
EOF
